155	// joinRepoPrefix puts an entry's prefix in front of the repository name.
156	//
157	// One slash, always: the prefix is a path segment and normalization has already
158	// refused one carrying a slash at either end, so there is nothing here to guess
159	// about (§3.18).
160	func joinRepoPrefix(prefix, repo string) string {
161		if prefix == "" {
162			return repo
163		}
164		return prefix + "/" + repo
165	}
