167	// normalizeRepoForRegistry prepends "library/" for bare names on Docker Hub.
168	func normalizeRepoForRegistry(registryURL, repo string) string {
169		if strings.Contains(repo, "/") {
170			return repo
171		}
172		if isDockerHub(registryURL) {
173			return "library/" + repo
174		}
175		return repo
176	}
