178	// registryHost strips the scheme from a configured registry URL, leaving what
179	// Docker itself is keyed on: `host[:port]`, plus whatever path a repository
180	// manager serves the registry under.
181	//
182	// A registry URL is written either way in practice — the form does not
183	// normalize it, `registryAPIURL` explicitly accepts both, and this package's own
184	// examples write `https://nexus.example.com/repository/docker-group`. Every
185	// Docker-facing use has to strip it, and none of the three that needed to did
186	// (D39): a `docker pull` reference carrying `https://` is not a reference at
187	// all, and a hub alias compared against a scheme-bearing string never matched,
188	// so images from a Hub configured as `https://docker.io` lost their `library/`
189	// prefix.
190	func registryHost(registryURL string) string {
191		base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
192		for _, scheme := range []string{"https://", "http://"} {
193			if len(base) >= len(scheme) && strings.EqualFold(base[:len(scheme)], scheme) {
194				return base[len(scheme):]
195			}
196		}
197		return base
198	}
