200	// isDockerHub reports whether a registry URL names Docker Hub, under either of
201	// the two spellings and with or without a scheme. Hub is the one registry whose
202	// references carry no host, so every caller has to recognise it.
203	func isDockerHub(registryURL string) bool {
204		host := registryHost(registryURL)
205		return strings.EqualFold(host, "docker.io") || strings.EqualFold(host, "registry-1.docker.io")
206	}
