208	// multiImageName constructs the full image reference for pull/scan.
209	//
210	// A Hub reference carries no host under docker: `docker pull nginx` leaves
211	// `nginx` as the local repository name, and qualifying it would only make the
212	// Images tab show `docker.io/library/nginx` next to a `nginx` pulled by hand.
213	// Podman disagrees, and not cosmetically — measured against a real podman
214	// with no `unqualified-search-registries` configured (§3.67), which is the
215	// package default on Debian/Ubuntu and Fedora alike: `podman pull
216	// library/nginx:tag` refuses outright ("short-name ... did not resolve to an
217	// alias and no unqualified-search registries are defined"), where docker
218	// would have silently assumed Hub. So the bare form is kept for docker, where
219	// it has always worked, and only podman gets the explicit host — which is
220	// also the form its own `images` list already uses (§3.67), so nothing about
221	// this makes a podman-pulled image look different from one already there.
222	func multiImageName(registryURL, repo, tag string) string {
223		if isDockerHub(registryURL) {
224			if engine.Current().Name == engine.Podman {
225				return "docker.io/" + repo + ":" + tag
226			}
227			return repo + ":" + tag
228		}
229		return registryHost(registryURL) + "/" + repo + ":" + tag

